  '<form\n  #formView="ngForm"\n  clrForm\n  clrLayout="vertical"\n  data-testid="policy-form"\n  [formGroup]="form"\n  (ngSubmit)="submit()"\n>\n  <clr-input-container>\n    <label for="policy-name">{{ \'selectionDemo.policyName\' | translate }}</label>\n    <input\n      id="policy-name"\n      data-testid="policy-form-name"\n      clrInput\n      formControlName="policyName"\n      [readonly]="readonly()"\n    />\n  </clr-input-container>\n\n  <app-namespace-picker\n    data-testid="policy-form-namespace"\n    formControlName="namespaceId"\n    required\n    [readonly]="readonly()"\n    [error]="namespaceSelectionError()"\n  />\n\n  <app-organization-picker\n    data-testid="policy-form-organizations"\n    formControlName="organizationIds"\n    required\n    [readonly]="readonly()"\n    [error]="orgSelectionError()"\n  />\n\n  <section\n    data-testid="policy-form-summary"\n    [attr.aria-label]="\'selectionDemo.selectedTitle\' | translate"\n    cds-layout="vertical gap:sm"\n  >\n    <p role="status" aria-atomic="true">\n      {{ \'selectionDemo.selectedCount\' | translate: selectedOrganizations().length : maximumOrganizations }}\n    </p>\n    <ul cds-layout="vertical gap:xs">\n      @for (selection of selectedOrganizations(); track selection.id) {\n        <li>\n          {{\n            selection.name ||\n              ((selection.unavailable ? \'selectionDemo.unavailableName\' : \'selectionDemo.unverifiedName\') | translate)\n          }}\n          ({{ selection.id }})\n          <button\n            type="button"\n            class="btn btn-link btn-sm"\n            [disabled]="selectionLocked()"\n            [attr.aria-label]="\'selectionDemo.removeKey\' | translate: selection.id"\n            (click)="removeSelection(selection.id)"\n          >\n            {{ \'selectionDemo.remove\' | translate }}\n          </button>\n        </li>\n      }\n    </ul>\n    @if (unavailableNamespaceId()) {\n      <clr-alert clrAlertType="warning" [clrAlertClosable]="false">\n        <clr-alert-item>\n          <span class="alert-text" role="alert">{{ \'selectionDemo.unavailableHelp\' | translate }}</span>\n        </clr-alert-item>\n      </clr-alert>\n    }\n    @if (hasUnavailableSelection()) {\n      <clr-alert data-testid="unavailable-selection" clrAlertType="warning" [clrAlertClosable]="false">\n        <clr-alert-item>\n          <span class="alert-text" role="alert">{{ \'selectionDemo.unavailableHelp\' | translate }}</span>\n          <div class="alert-actions">\n            <button type="button" class="btn btn-sm alert-action" (click)="retryVerification()">\n              {{ \'organizationExample.retry\' | translate }}\n            </button>\n          </div>\n        </clr-alert-item>\n      </clr-alert>\n    }\n    @if (warning()) {\n      <clr-alert data-testid="policy-form-warning" clrAlertType="warning" [clrAlertClosable]="false">\n        <clr-alert-item>\n          <span class="alert-text" role="alert">{{ \'policyExample.eligibilityWarning\' | translate }}</span>\n        </clr-alert-item>\n      </clr-alert>\n    }\n  </section>\n\n  @if (saved()) {\n    <clr-alert clrAlertType="success" [clrAlertClosable]="true">\n      <clr-alert-item>\n        <span class="alert-text" role="status">{{ \'policyExample.saved\' | translate }}</span>\n      </clr-alert-item>\n    </clr-alert>\n  }\n  @if (saveError()) {\n    <clr-alert data-testid="policy-form-save-error" clrAlertType="danger" [clrAlertClosable]="true">\n      <clr-alert-item>\n        <span class="alert-text" role="alert">{{ saveError() }}</span>\n      </clr-alert-item>\n    </clr-alert>\n  }\n\n  <div\n    class="selection-toolbar"\n    cds-layout="horizontal gap:md wrap:wrap"\n    role="group"\n    [attr.aria-label]="\'selectionDemo.policyControls\' | translate"\n  >\n    <label class="selection-toolbar-check">\n      <input type="checkbox" [checked]="readonly()" (change)="readonly.set(!readonly())" />\n      {{ \'selectionDemo.readonly\' | translate }}\n    </label>\n    <label class="selection-toolbar-check">\n      <input type="checkbox" [checked]="form.disabled" (change)="toggleDisabled()" />\n      {{ \'selectionDemo.disabled\' | translate }}\n    </label>\n    <label class="selection-toolbar-check">\n      <input\n        type="checkbox"\n        [checked]="layout() === \'horizontal\'"\n        (change)="layout.set(layout() === \'horizontal\' ? \'vertical\' : \'horizontal\')"\n      />\n      {{ \'selectionDemo.horizontal\' | translate }}\n    </label>\n    <label class="selection-toolbar-check">\n      {{ \'organizationExample.submit\' | translate }}\n      <select data-testid="policy-form-dto" [value]="dtoMode()" (change)="dtoMode.set($any($event.target).value)">\n        <option value="id-only">ID-only</option>\n        <option value="reference">Reference</option>\n        <option value="full-entity">Full entity</option>\n      </select>\n    </label>\n    <span class="selection-toolbar-spacer"></span>\n    <button type="button" class="btn btn-sm" (click)="reloadDetail()">\n      {{ \'selectionDemo.loadSaved\' | translate }}\n    </button>\n  </div>\n\n  <div cds-layout="horizontal gap:md wrap:wrap">\n    <button\n      type="submit"\n      data-testid="policy-form-save"\n      class="btn btn-primary"\n      [clrLoading]="saving()"\n      [disabled]="selectionLocked() || saving() || sf.invalid() || !verifiedOrgs() || !verifiedNamespaces()"\n    >\n      {{ \'organizationExample.submit\' | translate }}\n    </button>\n    <button type="button" class="btn btn-secondary" (click)="reset()">\n      {{ \'organizationExample.reset\' | translate }}\n    </button>\n  </div>\n</form>\n@if (submitted(); as savedDto) {\n  <p role="status" data-testid="policy-form-submitted">{{ \'policyExample.saved\' | translate }}</p>\n}\n<pre data-testid="policy-form-json" tabindex="0">{{ sf.submitValue() | json }}</pre>\n';
